class _NameFieldState extends State<NameField> {
  late final TextEditingController _controller;

  @override
  void initState() {
    super.initState();
    // Runs once per State: the next customer never gets here
    _controller = TextEditingController(text: widget.customer.name);
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => TextField(controller: _controller);
}

class _NameFieldState extends State<NameField> {
  late final TextEditingController _controller;

  @override
  void initState() {
    super.initState();
    _controller = TextEditingController(text: widget.customer.name);
  }

  @override
  void didUpdateWidget(NameField oldWidget) {
    super.didUpdateWidget(oldWidget);
    if (widget.customer.id == oldWidget.customer.id) return;
    _controller.text = widget.customer.name; // a new customer: new text
  }

  @override
  void dispose() {
    _controller.dispose();
    super.dispose();
  }

  @override
  Widget build(BuildContext context) => TextField(controller: _controller);
}
